import collections
import hashlib
import json
import subprocess
import sys
import tempfile
from pathlib import Path

p = Path(__file__).parent
root = Path('/home/hanbo/repo/delta-arrow-reader/experiments/spark-sql')
sys.path.insert(0, str(root))
from decimal_division import compare

load = lambda f: json.loads(f.read_text())
sha = lambda f: hashlib.sha256(f.read_bytes()).hexdigest()
checks = {}
for label, ref, result, corpus in [
    ('new', p/'spark.json', p/'after.json', root/'float-zero-comparisons.jsonl'),
    ('before-new', p/'spark.json', p/'before.json', root/'float-zero-comparisons.jsonl'),
    ('zero', p/'zero-spark.json', p/'after-zero-controls.json', p/'zero-controls.jsonl'),
]:
    checks[label] = compare(ref, result, corpus)
    (p/f'{label}-check.json').write_text(json.dumps(checks[label], indent=2)+'\n')
assert checks['new']['agreement'] == 240 and checks['new']['total'] == 256
assert checks['before-new']['agreement'] == 0
assert checks['zero']['agreement'] == checks['zero']['total'] == 8
before = {r['id']: r['actual'] for r in load(p/'before.json')['results']}
after = {r['id']: r['actual'] for r in load(p/'after.json')['results']}
reference = {r['id']: r['actual'] for r in load(p/'spark.json')['results']}
cases = {c['id']: c for c in load(p/'after.json')['cases']}
boundaries = []
for r in checks['new']['cases']:
    if not r['differences']:
        continue
    key = r['id']; a, b, expected = before[key], after[key], reference[key]
    scope = cases[key.rsplit('_', 1)[0]]['scope']
    assert r['differences'] == ['rows'], r
    if scope.startswith('boundary_'):
        assert a['rows'] == b['rows']
    else:
        assert scope == 'numeric_coercion' and key.endswith('_true')
        assert len(a['rows']) == len(b['rows']) == len(expected['rows'])
        for old, new, oracle in zip(a['rows'], b['rows'], expected['rows'], strict=True):
            assert new == oracle or new == old, (key, old, new, oracle)
    boundaries.append({'id': key, 'scope': scope, 'before_rows': a['rows'], 'after_rows': b['rows'], 'spark_rows': expected['rows']})
assert collections.Counter(r['scope'] for r in boundaries) == {'numeric_coercion':8, 'boundary_join_using':4, 'boundary_group_by':4}
(p/'remaining-boundaries.json').write_text(json.dumps(boundaries, indent=2)+'\n')

semantics = load(p/'semantics-check.json')
projected = {r['id']: r['actual'] for r in load(p/'after-projected.json')['results']}
for row in semantics['cases']:
    assert projected[row['id']]['status'] == 'ok'
    assert row['expected_rows'] == projected[row['id']]['rows']
    row['after_rows'] = projected[row['id']]['rows']
    row['after_agrees'] = True
assert len(semantics['cases']) == semantics['after_agreement'] == 264
(p/'semantics-check.json').write_text(json.dumps(semantics, indent=2)+'\n')

builds = {v: load(p / f'{v}built.json') for v in ['before-', '']}
a, b = builds['before-'], builds['']
for key in ['benchmark_sha256', 'lock_sha256', 'arrow_libraries', 'arrow_mod', 'arrow_reuse', 'arrow_decimal_sha256', 'cross_join_selection_sha256', 'nested_loop_sha256', 'optimizer_sources']:
    assert a[key] == b[key], key
assert sorted(a['dependencies'], key=lambda x:x['package_id']) == sorted(b['dependencies'], key=lambda x:x['package_id'])
assert [k for k in a['runtime'] if a['runtime'][k] != b['runtime'][k]] == ['common.rs']
assert sha(p/'candidate-common.rs') == b['runtime']['common.rs']
assert sha(p/'before-source-common.rs') == a['runtime']['common.rs']
assert (p/'verified-common-before-format.rs').read_text().split() == (p/'candidate-common.rs').read_text().split()
for v, built in [('before', a), ('after', b)]:
    for key, digest in built['binaries'].items():
        assert sha(p/f'{v}-{key}') == digest
identity = load(p/'build-identity.json') | {
    'before_common_sha256': a['runtime']['common.rs'], 'after_common_sha256': b['runtime']['common.rs'],
    'preformat_test_source_token_equivalent': True,
    'final_formatted_binary_replayed': ['6068 existing observations', '256 new observations', '8 signed-zero controls', '112 million-row benchmarks'],
}
(p/'build-identity.json').write_text(json.dumps(identity, indent=2)+'\n')

patch = root/'sail-float-comparison-zero.patch'
files = {
    'experiments/spark-sql/vendor/sail/crates/sail-plan/src/function/common.rs': ('before-source-common.rs','candidate-common.rs'),
    'experiments/spark-sql/examples/decimal_bench.rs': ('before-source-decimal_bench.rs','target-decimal_bench.rs'),
}
with tempfile.TemporaryDirectory(prefix='float-zero-patch-') as folder:
    folder = Path(folder)
    for rel, (old,new) in files.items():
        f = folder/rel; f.parent.mkdir(parents=True, exist_ok=True); f.write_bytes((p/old).read_bytes())
    for args in [['--check'], []]:
        subprocess.run(['git','apply',*args,str(patch)], cwd=folder, check=True)
    for rel, (old,new) in files.items():
        assert (folder/rel).read_bytes() == (p/new).read_bytes()
    subprocess.run(['git','apply','--reverse',str(patch)], cwd=folder, check=True)
    for rel, (old,new) in files.items():
        assert (folder/rel).read_bytes() == (p/old).read_bytes()
subprocess.run(['rustfmt','--edition','2024','--check',str(p/'candidate-common.rs')], check=True)
for kind in ['sources','executables']:
    records = load(p/('initial-sources.json' if kind=='sources' else 'initial-executables.json'))
    for key, record in records.items():
        file = Path(record['path'])
        if record.get('existed', True):
            assert sha(file) == record['sha256'], (kind,key)
        else:
            assert not file.exists(), (kind,key)
        if kind == 'executables':
            assert file.stat().st_mode & 0o777 == 0o755
record = {'patch_applies_and_reverses_exactly': True, 'rustfmt_common_passed': True,
          'final_captures_rechecked': True, 'remaining_row_differences_preexisting': True,
          'shared_sources_and_lockfiles_restored': 37, 'shared_executables_restored': 3}
(p/'final-verification.json').write_text(json.dumps(record, indent=2)+'\n')
print(record)
